// Validation des données d'entrée
const body = $input.first().json.body;

if (!body || !body.fileData) {
  throw new Error('fileData manquant dans la requête');
}
if (!body.periode || !/^\d{2}-\d{4}$/.test(body.periode)) {
  throw new Error('Période invalide. Format requis: MM-YYYY');
}
if (!body.gasUrl) {
  throw new Error('URL Google Apps Script manquante');
}

// Décoder le base64 en buffer
const buffer = Buffer.from(body.fileData, 'base64');

// Vérifier le header PDF
const header = buffer.slice(0, 5).toString('ascii');
const estPDF = header.startsWith('%PDF');

return [{
  json: {
    fileData: body.fileData,
    fileName: body.fileName || 'upload.pdf',
    periode: body.periode,
    gasUrl: body.gasUrl,
    estPDF: estPDF,
    tailleFichier: buffer.length,
    timestamp: new Date().toISOString()
  }
}];

// ── Récupérer le fileId retourné par GAS ─────────────────────────────────────
const gasReponse = $input.first().json;
const fileId = gasReponse.fileId || (gasReponse.data && gasReponse.data.fileId) || null;

if (!fileId) {
  throw new Error('GAS n\'a pas retourné de fileId. Réponse : ' + JSON.stringify(gasReponse).substring(0, 200));
}

const validationData = $("Validation des données d'entrée").item.json;
const fileData = validationData.fileData;
const gasUrl = validationData.gasUrl;
const periode = validationData.periode;
const buffer = Buffer.from(fileData, 'base64');

// ── Extraction NOM_Prenom sur lignes séparées ────────────────────────────────
function extraireNomPrenom(lignes) {
  for (const ligne of lignes.slice(0, 20)) {
    // Pattern 1 : MAJUSCULES Prénom isolé sur sa ligne — ex: "DUPONT Jean"
    const m1 = ligne.match(/^([A-ZÀÂÄÉÈÊËÏÎÙÛÜÇ][A-ZÀÂÄÉÈÊËÏÎÙÛÜÇ\-\']{1,})\s+([A-ZÀÂÄÉÈÊËÏÎÙÛÜÇ][a-zàâäéèêëïîùûüçœæ\-\']{1,})$/);
    if (m1) return m1[1].trim() + '_' + m1[2].trim();

    // Pattern 2 : label "Nom :", "Employé :", etc.
    const m2 = ligne.match(/(?:Nom|Employé|Collaborateur|Salarié)\s*[:\-]\s*([A-ZÀÂÄÉÈÊËÏÎÙÛÜÇ][a-zA-ZÀ-ÿ\s\-\']{2,})/i);
    if (m2) {
      const parts = m2[1].trim().split(/\s+/);
      if (parts.length >= 2) return parts[0].toUpperCase() + '_' + parts[1];
    }

    // Pattern 3 : Prénom NOM — ex: "Jean DUPONT"
    const m3 = ligne.match(/^([A-ZÀÂÄÉÈÊËÏÎÙÛÜÇ][a-zàâäéèêëïîùûüçœæ\-\']{1,})\s+([A-ZÀÂÄÉÈÊËÏÎÙÛÜÇ]{2,})$/);
    if (m3) return m3[2] + '_' + m3[1];
  }
  return '';
}

// ── Extraction texte par page via coordonnées Y ───────────────────────────────
async function extractPageLines(pdfPage) {
  const content = await pdfPage.getTextContent();
  const lineMap = new Map();
  for (const item of content.items) {
    if (!item.str || !item.str.trim()) continue;
    const y = Math.round(item.transform[5]);
    if (!lineMap.has(y)) lineMap.set(y, []);
    lineMap.get(y).push({ x: item.transform[4], str: item.str });
  }
  const sortedYs = [...lineMap.keys()].sort((a, b) => b - a);
  return sortedYs.map(y => {
    return lineMap.get(y).sort((a, b) => a.x - b.x).map(i => i.str).join(' ').trim();
  }).filter(l => l.length > 0);
}

let pages = [];

try {
  // pdfjs-dist v4+ est ESM — utiliser await import()
  const pdfjsLib = await import('pdfjs-dist/legacy/build/pdf.mjs');
  const loadingTask = pdfjsLib.getDocument({ data: new Uint8Array(buffer) });
  const pdfDoc = await loadingTask.promise;
  const numPages = pdfDoc.numPages;

  // Charger pdf-lib pour le découpage page par page
  let pdfDocLib = null;
  try {
    const { PDFDocument } = await import('pdf-lib');
    pdfDocLib = await PDFDocument.load(buffer);
  } catch (e) { /* pdf-lib absent — fallback PDF complet */ }

  for (let i = 1; i <= numPages; i++) {
    const page = await pdfDoc.getPage(i);
    const lignes = await extractPageLines(page);
    const nomPrenom = extraireNomPrenom(lignes);

    // Découpage individuel si pdf-lib disponible
    let pageBase64 = null;
    if (pdfDocLib) {
      try {
        const { PDFDocument: PDFDoc } = await import('pdf-lib');
        const singleDoc = await PDFDoc.create();
        const [cp] = await singleDoc.copyPages(pdfDocLib, [i - 1]);
        singleDoc.addPage(cp);
        const bytes = await singleDoc.save();
        pageBase64 = Buffer.from(bytes).toString('base64');
      } catch (e) { /* découpage échoué pour cette page */ }
    }

    pages.push({
      pageIndex: i - 1,
      texte: lignes.slice(0, 5).join(' | '),
      nomPrenom,
      pageBase64
    });
  }

} catch (error) {
  // ── Fallback : appel GAS pour extraction via Drive PDF→Google Doc ──────────
  console.log('pdfjs-dist indisponible (' + error.message.substring(0, 100) + ') — appel GAS extrairePDF');
  try {
    const gasResponse = await fetch(gasUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'extrairePDF', fileId })
    });
    const gasData = await gasResponse.json();
    if (gasData.success && Array.isArray(gasData.pages) && gasData.pages.length > 0) {
      pages = gasData.pages;
    } else {
      const errMsg = gasData.error || 'Réponse GAS vide';
      pages = [{
        pageIndex: 0,
        texte: 'Extraction GAS échouée — ' + errMsg,
        nomPrenom: '',
        pageBase64: null
      }];
    }
  } catch (fetchError) {
    pages = [{
      pageIndex: 0,
      texte: 'Extraction impossible — ' + fetchError.message,
      nomPrenom: '',
      pageBase64: null
    }];
  }
}

return [{ json: { pages, totalPages: pages.length, fileId, gasUrl, periode } }];

// Faire correspondre chaque page avec un salarié
const extraitData = $("Extraire le texte du PDF").item.json;
const pages = extraitData.pages;
const fileId = extraitData.fileId;
const periode = extraitData.periode;

// La réponse GAS peut être un tableau direct ou encapsulée
const gasReponse = $input.first().json;
let salaries = [];
if (Array.isArray(gasReponse)) {
  salaries = gasReponse;
} else if (Array.isArray(gasReponse.salaries)) {
  salaries = gasReponse.salaries;
} else if (Array.isArray(gasReponse.data)) {
  salaries = gasReponse.data;
}

// Normaliser une chaîne pour comparaison insensible aux accents/casse
function normaliser(str) {
  if (!str) return '';
  return str
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toUpperCase()
    .replace(/[^A-Z0-9_]/g, '');
}

// Construire un index normalisé des salariés pour le matching rapide
const indexSalaries = {};
for (const s of salaries) {
  if (s.nomPrenom) {
    indexSalaries[normaliser(s.nomPrenom)] = s;
  }
}

const resultatsMatching = [];
const nonTrouves = [];
const emailsManquants = [];

for (const page of pages) {
  const nomPrenomBrut = page.nomPrenom || '';
  const nomPrenomNorm = normaliser(nomPrenomBrut);

  // Chercher d'abord par correspondance exacte normalisée
  let salarie = indexSalaries[nomPrenomNorm] || null;

  // Si pas trouvé, essayer une correspondance partielle (préfixe NOM)
  if (!salarie && nomPrenomNorm.length > 2) {
    const nomSeul = nomPrenomNorm.split('_')[0];
    if (nomSeul) {
      for (const [key, val] of Object.entries(indexSalaries)) {
        if (key.startsWith(nomSeul + '_') || key === nomSeul) {
          salarie = val;
          break;
        }
      }
    }
  }

  if (!salarie) {
    nonTrouves.push(nomPrenomBrut || 'Page ' + page.pageIndex);
    resultatsMatching.push({
      ...page,
      statut: 'NON_TROUVE',
      email: null,
      inclure: false
    });
  } else if (!salarie.email) {
    emailsManquants.push(salarie.nomPrenom);
    resultatsMatching.push({
      ...page,
      nomPrenom: salarie.nomPrenom,
      statut: 'EMAIL_MANQUANT',
      email: null,
      idDossierDrive: salarie.idDossierDrive,
      inclure: true
    });
  } else {
    resultatsMatching.push({
      ...page,
      nomPrenom: salarie.nomPrenom,
      statut: 'OK',
      email: salarie.email,
      idDossierDrive: salarie.idDossierDrive,
      inclure: true
    });
  }
}

return [{
  json: {
    mapping: resultatsMatching,
    nonTrouves,
    emailsManquants,
    nbTotal: resultatsMatching.length,
    nbOk: resultatsMatching.filter(m => m.statut === 'OK').length,
    nbProblemes: nonTrouves.length + emailsManquants.length,
    fileId,
    periode
  }
}];
